import React, { useState } from 'react';

function StudentForm() {
  const [formData, setFormData] = useState({
    nume: '',
    prenume: '',
    facultate: '',
    motivatie: ''
  });
  const [errors, setErrors] = useState({});
  
  const handleChange = (e) => {
    setFormData({...formData, [e.target.name]: e.target.value});
  };

  const validate = () => {
    const errors = {};
    if (!formData.nume) errors.nume = "Nume este obligatoriu.";
    if (!formData.prenume) errors.prenume = "Prenume este obligatoriu.";
    if (!formData.facultate) errors.facultate = "Facultatea este obligatorie.";
    if (!formData.motivatie || formData.motivatie.length < 100) {
      errors.motivatie = "Motivație trebuie să aibă minim 100 de caractere.";
    }
    return errors;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const validationErrors = validate();
    if (Object.keys(validationErrors).length) {
      setErrors(validationErrors);
      return;
    }

    // Trimite datele către API-ul backend-ului
    try {
      const response = await fetch('http://localhost:5000/api/studentforms', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(formData)
      });
      
      if (response.ok) {
        // Obținem PDF-ul ca blob și-l descărcăm
        const blob = await response.blob();
        const url = window.URL.createObjectURL(new Blob([blob]));
        const link = document.createElement('a');
        link.href = url;
        link.setAttribute('download', 'FisăStudent.pdf'); 
        document.body.appendChild(link);
        link.click();
        link.parentNode.removeChild(link);
        setFormData({ nume: '', prenume: '', facultate: '', motivatie: '' });
        setErrors({});
      } else {
        console.error("Eroare la trimitere!");
      }
    } catch (error) {
      console.error("Eroare la conectare cu API-ul:", error);
    }
  };

  return (
    <div>
      <h2>Formular Student</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label>Nume:</label>
          <input type="text" name="nume" value={formData.nume} onChange={handleChange} />
          {errors.nume && <span style={{color: 'red'}}>{errors.nume}</span>}
        </div>
        <div>
          <label>Prenume:</label>
          <input type="text" name="prenume" value={formData.prenume} onChange={handleChange} />
          {errors.prenume && <span style={{color: 'red'}}>{errors.prenume}</span>}
        </div>
        <div>
          <label>Facultate:</label>
          <input type="text" name="facultate" value={formData.facultate} onChange={handleChange} />
          {errors.facultate && <span style={{color: 'red'}}>{errors.facultate}</span>}
        </div>
        <div>
          <label>Motivație participare:</label>
          <textarea name="motivatie" value={formData.motivatie} onChange={handleChange} />
          {errors.motivatie && <span style={{color: 'red'}}>{errors.motivatie}</span>}
        </div>
        <button type="submit">Trimite</button>
      </form>
    </div>
  );
}

export default StudentForm;
